// The host elements: div and text (a text run), plus Fragment, whose
// children lower as their parent's direct children (no wrapper), and
// slot — the plugin seam: a container whose children the slot
// registry owns (ticket 67).
interface HostElement {}

declare namespace JSX {
	interface Element extends HostElement {}
	interface IntrinsicElements {
		Fragment: HostProps;
		div: HostProps;
		slot: SlotProps;
		text: HostProps;
	}
}

interface HostProps {
	children?: Child | Child[];
	className?: string;
	id?: string;
	key?: string;
	onClick?: (event: MouseEvent) => void;
	onMouseDown?: (event: MouseEvent) => void;
	style?: CSSProperties;
}

// The slot element (the app side of plugins): a div-like container
// whose children the slot registry owns — the plugins registered for
// its name contribute them, in registration order; its JSX children
// are the fallback shown while no plugin fills it (a web component's
// slot).
interface SlotProps extends HostProps {
	/** The slot's name: which plugins' contributions fill it. */
	name: string;
}

// A slot component receives the name of the slot instance it fills.
interface PluginSlotProps {
	/** The name of the slot this component was called for. */
	slot: string;
}

// A slot component: called once per (re)load and per re-describe, it
// describes that slot's content (an element tree, like App).
interface SlotComponent {
	(props: PluginSlotProps): HostElement;
}

// The manifest a plugin bundle exports as its entry: the slots it
// fills, by name, and the component describing each. The app grants
// what the plugin may reach (script.Slots' Grants); a plugin reaching
// past its grants gets a named error.
interface PluginManifest {
	/** The slots this plugin contributes to, keyed by slot name. */
	slots: Record<string, SlotComponent>;
}

// The event object handlers receive (DOM-shaped: the mouse button as
// the DOM's numbers, the position in window px, the modifier keys).
interface MouseEvent {
	button: number;
	x: number;
	y: number;
	shiftKey: boolean;
	ctrlKey: boolean;
	altKey: boolean;
	metaKey: boolean;
}

// The style object's CSS properties (camelCase, as in React), with the
// value shapes the engine accepts; anything else is a load error that
// names the .tsx line.
interface CSSProperties {
	/** display: flex, block. */
	display?: "flex" | "block";
	/** flexDirection: row, column. */
	flexDirection?: "row" | "column";
	/** alignItems: center, flex-start, start, flex-end, end. */
	alignItems?: "center" | "flex-start" | "start" | "flex-end" | "end";
	/** justifyContent: center, flex-start, start, flex-end, end, space-between. */
	justifyContent?: "center" | "flex-start" | "start" | "flex-end" | "end" | "space-between";
	/** flex: 1 (the only flex value the engine applies). */
	flex?: 1;
	/** gap: a px length (8 or "8px"). */
	gap?: number | `${number}px`;
	/** width: a px length, or "100%". */
	width?: "100%" | number | `${number}px`;
	/** height: a px length, or "100%". */
	height?: "100%" | number | `${number}px`;
	/** minHeight: a px length. */
	minHeight?: number | `${number}px`;
	/** padding: one, two or four px lengths ("8", "8 16", "8 16 8 16"). */
	padding?: number | `${number}px` | `${number} ${number}` | `${number} ${number}px` | `${number}px ${number}` | `${number}px ${number}px` | `${number} ${number} ${number} ${number}` | `${number} ${number} ${number} ${number}px` | `${number} ${number} ${number}px ${number}` | `${number} ${number} ${number}px ${number}px` | `${number} ${number}px ${number} ${number}` | `${number} ${number}px ${number} ${number}px` | `${number} ${number}px ${number}px ${number}` | `${number} ${number}px ${number}px ${number}px` | `${number}px ${number} ${number} ${number}` | `${number}px ${number} ${number} ${number}px` | `${number}px ${number} ${number}px ${number}` | `${number}px ${number} ${number}px ${number}px` | `${number}px ${number}px ${number} ${number}` | `${number}px ${number}px ${number} ${number}px` | `${number}px ${number}px ${number}px ${number}` | `${number}px ${number}px ${number}px ${number}px`;
	/** background: a CSS hex color (#rrggbb). */
	background?: `#${string}`;
	/** color: a CSS hex color. */
	color?: `#${string}`;
	/** borderColor: a CSS hex color. */
	borderColor?: `#${string}`;
	/** border: a px length. */
	border?: number | `${number}px`;
	/** borderRadius: a px length. */
	borderRadius?: number | `${number}px`;
	/** fontSize: a px length. */
	fontSize?: number | `${number}px`;
	/** fontWeight: a number (100–900). */
	fontWeight?: number;
	/** opacity: a number (0–1). */
	opacity?: number;
	/** overflowY: scroll, auto, hidden. */
	overflowY?: "scroll" | "auto" | "hidden";
	/** overflowFade: one, two or four px lengths — the overflow edge fades. */
	overflowFade?: number | `${number}px` | `${number} ${number}` | `${number} ${number}px` | `${number}px ${number}` | `${number}px ${number}px` | `${number} ${number} ${number} ${number}` | `${number} ${number} ${number} ${number}px` | `${number} ${number} ${number}px ${number}` | `${number} ${number} ${number}px ${number}px` | `${number} ${number}px ${number} ${number}` | `${number} ${number}px ${number} ${number}px` | `${number} ${number}px ${number}px ${number}` | `${number} ${number}px ${number}px ${number}px` | `${number}px ${number} ${number} ${number}` | `${number}px ${number} ${number} ${number}px` | `${number}px ${number} ${number}px ${number}` | `${number}px ${number} ${number}px ${number}px` | `${number}px ${number}px ${number} ${number}` | `${number}px ${number}px ${number} ${number}px` | `${number}px ${number}px ${number}px ${number}` | `${number}px ${number}px ${number}px ${number}px`;
	/** mixBlendMode: normal, multiply, screen, overlay, darken, lighten, color-dodge, color-burn, hard-light, soft-light, difference, exclusion, hue, saturation, color, luminosity, plus-lighter. */
	mixBlendMode?: "normal" | "multiply" | "screen" | "overlay" | "darken" | "lighten" | "color-dodge" | "color-burn" | "hard-light" | "soft-light" | "difference" | "exclusion" | "hue" | "saturation" | "color" | "luminosity" | "plus-lighter";
	/** isolation: isolate, auto. */
	isolation?: "isolate" | "auto";
	/** clipPath: a CSS basic shape — circle(40px), ellipse(30% 50%), inset(10px 20px), polygon(50% 0, 100% 100%, 0 100%). */
	clipPath?: string;
	/** maskImage: linear-gradient(to bottom, #000000, #00000000) — a linear gradient mask with hex stops. */
	maskImage?: string;
	/** dropShadow: one or more CSS drop-shadow values — "0 4px 6px #00000040". */
	dropShadow?: string;
}

// Children are elements, text, numbers, bindings, arrays and
// false/undefined/null (skipped, so {cond && <x />} works).
type Child = string | number | boolean | null | undefined | HostElement | Child[];

// The keyed-state handle (state and shared): set recomputes only the
// bindings on that key, without re-describing the tree.
interface StateHandle<S> {
	key: string;
	get(): S;
	set(value: S): void;
}

